        throw UndraCallError.mapped(e)
    }
}

/**
 * Marks an item of `list` finished or not, showing the change at once and taking it back if the server
 * refuses.
 * @throws RemoteError
 * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
 * @throws CancellationException if the calling coroutine is cancelled.
 */
suspend fun setRemoteDone(
    list: String,
    id: UInt,
    done: Boolean,
    ctx: UndraCore = UndraPlaygroundCore.core,
): RemoteTodo {
    val w = UndraWriter()
    w.writeStr(list)
    w.writeU32(id)
    w.writeBool(done)
    try {
        val body = ctx.call(
            CallTarget.FreeFunction(UndraIds.Functions.SET_REMOTE_DONE),
            UndraIds.Functions.SET_REMOTE_DONE,
            w.toByteArray(),
        )
        return RemoteTodo.decodeAll(body)
    } catch (e: Exception) {
        throw UndraCallError.mapped(e, RemoteError)
    }
}

/**
 * The name and version of the core.
 * @throws UndraCallError if the core panics, refuses or cancels the call, or cannot be reached.
 */
fun version(ctx: UndraCore = UndraPlaygroundCore.core): String {
    try {
        val body = ctx.callSync(
            CallTarget.FreeFunction(UndraIds.Functions.VERSION),
            UndraIds.Functions.VERSION,
            ByteArray(0),
        )
        return Codecs.string.decodeAll(body)
    } catch (e: Exception) {
        throw UndraCallError.mapped(e)
    }
}

private val codecVecString = Codecs.vec(Codecs.string)
private val codecOptionU32 = Codecs.option(Codecs.u32)
private val codecOptionBytes = Codecs.option(Codecs.bytes)
